<script>
  import { onMount, onDestroy } from 'svelte';
  import { nbaCalendarUrl, nbaCalendarRows } from '$lib/product/calendar.js';
  import { teamStyle, totalLineFor } from '$lib/product/teams.js';
  let dayIndex=0, search='', games=[], selectedId=null, loading=true, unavailable=false, fetchedAt=null, mounted=false, signature=-1;
  let controller, generation=0;
  $: filtered=games.filter(game=>`${game.home_team.full_name} ${game.visitor_team.full_name}`.toLocaleLowerCase('es').includes(search.trim().toLocaleLowerCase('es')));
  $: selected=filtered.find(game=>game.id===selectedId)||filtered[0];
  $: if(mounted && signature!==dayIndex){signature=dayIndex;load();}
  // Market totals (cached server-side, public): the O/U next to each game.
  let lines=null;
  onMount(()=>{mounted=true;fetch('/api/odds/nba-totals').then(async r=>{const b=await r.json();lines=r.ok&&Array.isArray(b.events)?b:null;}).catch(()=>{lines=null;});});
  const fmtLine=n=>n.toLocaleString('es',{maximumFractionDigits:1});
  onDestroy(()=>{generation++;controller?.abort();});
  async function load(){
    const run=++generation;controller?.abort();controller=new AbortController();
    loading=true;unavailable=false;games=[];selectedId=null;fetchedAt=null;
    try{
      const response=await fetch(nbaCalendarUrl(Date.now(),dayIndex),{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(15000)])});
      const body=await response.json();const rows=nbaCalendarRows(response,body);
      if(run===generation){games=rows;fetchedAt=new Date();}
    }catch{if(run===generation)unavailable=true;}
    finally{if(run===generation)loading=false;}
  }
  function readableStatus(game){
    const value=game.status||'';
    if(value==='Final')return 'Finalizado';
    const timestamp=Date.parse(value);
    // Local time, like every other NBA screen (the day itself follows the NBA's New York calendar).
    if(value.includes('T')&&Number.isFinite(timestamp))return new Intl.DateTimeFormat('es',{hour:'2-digit',minute:'2-digit'}).format(timestamp);
    return value||'Horario sin confirmar';
  }
</script>

<div class="nba">
  <header class="page-head"><span class="eyebrow">NBA · Calendario</span><h1>Partidos</h1><p>Hoy y mañana, con fuente y hora. Elige un partido para ver su contexto y abrir sus props.</p></header>
  <div class="toolbar"><div class="days" role="group" aria-label="Día NBA"><button class:active={dayIndex===0} aria-pressed={dayIndex===0} on:click={()=>dayIndex=0}>Hoy</button><button class:active={dayIndex===1} aria-pressed={dayIndex===1} on:click={()=>dayIndex=1}>Mañana</button></div><label class="search"><span>Buscar equipo</span><input type="search" bind:value={search} placeholder="Lakers, Celtics…"/></label><button class="refresh" on:click={load} disabled={loading}>{loading?'Consultando…':'Actualizar calendario'}</button></div>
  {#if loading}<div class="empty" role="status"><div class="loader"></div><h2>Consultando la jornada.</h2><p>Estamos comprobando el calendario del proveedor.</p></div>
  {:else if unavailable}<div class="empty" role="alert"><span class="empty-icon" aria-hidden="true">↗</span><h2>La jornada necesita una fuente disponible.</h2><p>No pudimos confirmar los partidos. Puedes reintentar o consultar cómo se construye el análisis mientras se restablece la información.</p><div class="empty-actions"><button on:click={load}>Reintentar consulta</button><a href="/methodology">Conocer la metodología ↗</a></div></div>
  {:else}
    <div class="source"><span>Partidos: balldontlie · consultado {fetchedAt?.toLocaleTimeString('es',{hour:'2-digit',minute:'2-digit'})} · hora local{#if lines}{' · '}líneas O/U: {lines.source}{/if}</span><span>{filtered.length} partidos en esta vista</span></div>
    {#if filtered.length===0}<div class="empty"><h2>{search?'Ningún equipo coincide con tu búsqueda.':'Sin encuentros en el calendario recibido.'}</h2><p>{search?'Prueba con otro equipo o limpia la búsqueda.':'La cobertura recibida no contiene partidos para el día seleccionado.'}</p>{#if search}<button on:click={()=>search=''}>Limpiar búsqueda</button>{/if}</div>
    {:else}<div class="workspace"><aside class="schedule" aria-label="Partidos NBA">{#each filtered as game(game.id)}{@const ou=totalLineFor(game,lines)}<button class="match" class:selected={selected?.id===game.id} aria-pressed={selected?.id===game.id} on:click={()=>selectedId=game.id}><span class="match-status">{readableStatus(game)}{#if ou}<em class="ou">O/U {fmtLine(ou.point)}</em>{/if}</span><strong><i class="mono" style={teamStyle(game.visitor_team.abbreviation)}>{game.visitor_team.abbreviation}</i>{game.visitor_team.full_name}</strong><span class="match-vs">visita a</span><strong><i class="mono" style={teamStyle(game.home_team.abbreviation)}>{game.home_team.abbreviation}</i>{game.home_team.full_name}</strong><span class="match-foot">Ver contexto <b>↗</b></span></button>{/each}</aside><section class="report" aria-label="Contexto del partido"><div class="report-top"><span class="eyebrow">EL ENCUENTRO</span><span>{readableStatus(selected)}</span></div><div class="versus"><div><span class="team-mark" style={teamStyle(selected.visitor_team.abbreviation)}>{selected.visitor_team.abbreviation||'V'}</span><small>VISITANTE</small><h2>{selected.visitor_team.full_name}</h2></div><b class="vs">VS</b><div><span class="team-mark home-team" style={teamStyle(selected.home_team.abbreviation)}>{selected.home_team.abbreviation||'L'}</span><small>LOCAL</small><h2>{selected.home_team.full_name}</h2></div></div>{#if selected.status==='Final'&&Number.isFinite(selected.visitor_team_score)&&Number.isFinite(selected.home_team_score)}<p class="score">Resultado final <strong>{selected.visitor_team_score} — {selected.home_team_score}</strong></p>{/if}{#if totalLineFor(selected,lines)}<p class="score">Total del partido en las casas <strong>O/U {fmtLine(totalLineFor(selected,lines).point)}</strong> <small>mediana de {totalLineFor(selected,lines).books} casas</small></p>{/if}<div class="context-note"><h2>Analiza este partido.</h2><p>Jugadores frente a su línea, puntos de cada equipo y total del partido. Lesiones y descansos requieren confirmación aparte.</p></div><div class="links"><a class="analysis-link" href={`/sports/nba/props?game=${selected.id}`}>Props de jugadores ↗</a><a class="analysis-link" href={`/sports/nba/puntos?game=${selected.id}`}>Mercado de puntos ↗</a></div></section></div>{/if}
  {/if}
</div>

<style>
 .mono{display:inline-grid;place-items:center;width:34px;height:20px;margin-right:8px;border-radius:5px;background:var(--team);color:var(--team-ink,#fff);font-style:normal;font-family:var(--font-display);font-size:11px;font-weight:700;letter-spacing:.04em;vertical-align:1px}.ou{margin-left:8px;font-style:normal;font-weight:700;color:var(--nio-accent)}.links{display:grid;grid-template-columns:1fr 1fr;gap:10px}.links .analysis-link{margin:0}@media(max-width:760px){.links{grid-template-columns:1fr}}
.page-head{margin:0 0 18px}.page-head .eyebrow{display:block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:600;color:var(--nio-muted);margin:0 0 8px}.page-head h1{font-family:var(--font-display);text-transform:uppercase;font-weight:800;font-size:clamp(34px,4.2vw,52px);line-height:.95;margin:0 0 10px}.page-head p{color:var(--nio-muted);max-width:640px;margin:0;line-height:1.6}.nba{--ink:var(--nio-ink);--muted:var(--nio-muted);--surface:var(--nio-surface);--raised:var(--nio-raised);--line:var(--nio-border);--accent:var(--nio-accent);--selection:var(--nio-selection);max-width:1320px;margin:auto;padding:8px 24px 90px;color:var(--ink);font-family:var(--font-sans);position:relative;font-variant-numeric:tabular-nums}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer;color:inherit}a:focus-visible,button:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.eyebrow{font-size:11px;letter-spacing:.14em;font-weight:700}h1{font-family:var(--font-display);text-transform:uppercase;font-size:clamp(46px,5.6vw,80px);font-weight:800;letter-spacing:0;line-height:.94;margin:22px 0}h2{font-weight:650;letter-spacing:-.025em}.toolbar{display:flex;align-items:center;gap:15px;flex-wrap:wrap;margin-bottom:22px}.days{display:flex;gap:5px;padding:5px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}button{border:1px solid var(--line);border-radius:7px;background:var(--surface);padding:10px 15px;font-size:13px;min-height:44px}button:hover{border-color:var(--accent)}button:disabled{opacity:.6;cursor:wait}.days button{border:0;background:transparent;color:var(--muted);min-width:80px}.days .active{background:var(--selection);color:var(--accent);font-weight:700}.search{display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:0 12px}.search span{font-size:12px;color:var(--muted)}.search input{min-width:100px;width:180px;padding:10px 0;background:transparent;border:0;color:var(--ink);font-size:14px}.search input::placeholder{color:var(--muted);opacity:1}.refresh{margin-left:auto}.empty{border:1px solid var(--line);background:var(--surface);border-radius:14px;text-align:center;padding:42px 24px}.empty-icon{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);border-radius:50%;margin:0 auto 18px;color:var(--accent);font-size:25px}.empty h2{font-size:22px}.empty p{font-size:14px;color:var(--muted);max-width:550px;line-height:1.8;margin:14px auto 20px}.empty-actions{display:flex;align-items:center;justify-content:center;gap:22px;flex-wrap:wrap}.empty-actions a{font-size:13px;color:var(--accent)}.loader{height:26px;width:26px;border:2px solid var(--line);border-top-color:var(--accent);border-radius:50%;margin:0 auto 18px;animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.source{display:flex;justify-content:space-between;gap:15px;margin-bottom:15px;color:var(--muted);font-size:12px}.workspace{display:grid;grid-template-columns:290px minmax(0,1fr);gap:20px}.schedule{display:flex;flex-direction:column;gap:10px;max-height:620px;overflow:auto}.match{display:flex;flex-direction:column;text-align:left;padding:20px;flex-shrink:0}.match.selected{background:var(--selection);border-color:var(--accent)}.match-status{font-size:12px;color:var(--muted);margin-bottom:16px}.match strong{font-size:15px}.match-vs{font-size:12px;color:var(--muted);margin:5px 0}.match-foot{display:flex;justify-content:space-between;align-items:center;width:100%;font-size:12px;padding-top:14px;margin-top:15px;border-top:1px solid var(--line);color:var(--accent)}.report{padding:28px;border:1px solid var(--line);border-radius:14px;background:var(--surface);min-width:0}.report-top{display:flex;justify-content:space-between;gap:14px;color:var(--muted);font-size:12px}.versus{display:grid;grid-template-columns:1fr 40px 1fr;gap:12px;text-align:center;align-items:center;padding:30px 0}.team-mark{display:grid;place-items:center;width:66px;height:66px;border-radius:20px;background:var(--team,var(--raised));color:var(--team-ink,var(--ink));font-size:20px;font-weight:700;margin:0 auto 14px}.versus small{font-size:11px;color:var(--muted)}.versus h2{font-size:20px;margin-top:10px}.vs{font-size:12px;color:var(--muted)}.score{text-align:center;color:var(--muted);font-size:13px}.score strong{display:block;font-size:30px;color:var(--ink);margin-top:8px}.context-note{border-top:1px solid var(--line);padding-top:22px;margin-top:10px}.context-note h2{font-size:17px}.context-note p{font-size:14px;line-height:1.8;color:var(--muted);margin:10px 0 20px}.analysis-link{display:flex;align-items:center;justify-content:center;min-height:48px;border:1px solid var(--line);border-radius:8px;color:var(--accent);font-size:14px;font-weight:700}
 @media(max-width:760px){.nba{padding:4px 16px 90px}.search{flex:1}.search input{width:100%}.refresh{margin-left:0}.workspace{grid-template-columns:1fr}.schedule{max-height:none;overflow:visible}.report{padding:20px}.versus{gap:8px;grid-template-columns:1fr 24px 1fr}.versus h2{font-size:17px}.source{flex-direction:column}.toolbar{gap:12px}.toolbar .search{flex-basis:100%}}
 @media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style>
